1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"database/sql"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"time"
12	
13		_ "modernc.org/sqlite"
14	)
15	
16	// InitialStage is the stage every incident starts in when it is registered.
17	const InitialStage = "受理"
18	
19	// stageOrder lists the stages in the only order an incident may advance.
20	// Transitions move exactly one step forward along this list.
21	var stageOrder = []string{"受理", "遏制", "清除", "恢复", "关闭"}
22	
23	// nextStage returns the stage that immediately follows current, or false when
24	// current is the final stage (or otherwise has no successor).
25	func nextStage(current string) (string, bool) {
26		for i, stage := range stageOrder[:len(stageOrder)-1] {
27			if stage == current {
28				return stageOrder[i+1], true
29			}
30		}
31		return "", false
32	}
33	
34	// TimelineEntry records one stage of an incident's life together with the
35	// owner responsible at that point and the UTC time the entry was created.
36	type TimelineEntry struct {
37		Stage string `json:"stage"`
38		Owner string `json:"owner"`
