}

func TestTransitionValidatesBeforeLookup(t *testing.T) {
	server, _ := newTestRouter(t)

	// Invalid bodies are rejected before the id is ever looked up.
	invalid := []string{
		`{"stage":"unknown","owner":"bob"}`,
		`{"Stage":"遏制","owner":"bob"}`,
		`{"stage":"遏制","owner":"bob","owner":"carol"}`,
